package org.viridexa.api.workbench;

import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Bounded read projections over the existing two sample ledgers. No secondary scientific store. */
@Repository
public class WorkbenchRepository {
 private final JdbcTemplate jdbc;
 public WorkbenchRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public record Filters(String q,Long plantId,String sourceId,String kind,String plantPart,String status,Boolean unlinked){}
 private static String published(boolean admin){return admin?"":" JOIN public_source_record f ON f.id=o.candidate_id ";}
 private static String state(){return "COALESCE(r.state,IF(c.normalization_state='HELD','HELD','PENDING'))";}
 private String scientificExists(boolean admin,Filters f,List<Object> args){String sql=" EXISTS(SELECT 1 FROM scientific_lipid_observation o JOIN scientific_candidate c ON c.id=o.candidate_id LEFT JOIN scientific_review_state r ON r.candidate_id=c.id "+published(admin)+" WHERE o.sample_id=sm.id";
  if(f.kind()!=null){sql+=" AND o.kind=?";args.add(f.kind());}if(f.sourceId()!=null){sql+=" AND (sm.source_id=? OR o.source_id=?)";args.add(f.sourceId());args.add(f.sourceId());}if(f.plantPart()!=null){sql+=" AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.plant_part')),JSON_UNQUOTE(JSON_EXTRACT(c.normalized_payload,'$.plantPart'))) =?";args.add(f.plantPart());}if(f.status()!=null){sql+=" AND "+state()+"=?";args.add(f.status());}return sql+")";}
 public List<Map<String,Object>> samples(boolean admin,Filters f,String after,int size){var args=new ArrayList<Object>();String where=" WHERE CONCAT('sample:',sm.id)>? ";args.add(after);where+=" AND "+scientificExists(admin,f,args);
  // The independent scientific ledger has no plant FK. A textual name is not an identity link.
  if(f.plantId()!=null)where+=" AND 1=0";if(Boolean.FALSE.equals(f.unlinked()))where+=" AND 1=0";
  if(f.q()!=null){where+=" AND (sm.sample_key LIKE ? ESCAPE '!' OR sm.study_key LIKE ? ESCAPE '!'"+" OR sm.identity_text LIKE ? ESCAPE '!'"+")";args.add(like(f.q()));args.add(like(f.q()));args.add(like(f.q()));}
  args.add(size);
  var result=new ArrayList<>(jdbc.queryForList("SELECT CONCAT('sample:',sm.id) AS id,sm.id AS native_id,sm.sample_key,sm.study_key,"+"LEFT(COALESCE(sm.identity_text,sm.sample_key),500)"+" AS label,NULL AS plant_id,NULL AS taxon_id,'UNLINKED' AS identity_state,NULL AS plant_part,NULL AS method,'UNLINKED' AS linkage_state,sm.source_id,(SELECT COUNT(*) FROM scientific_lipid_observation o "+published(admin)+" WHERE o.sample_id=sm.id) AS measurement_count FROM scientific_sample sm"+where+" ORDER BY sm.id LIMIT ?",args.toArray()));
  if(admin){args=new ArrayList<>();where=" WHERE CONCAT('course-sample:',sm.id)>? ";args.add(after);if(f.plantId()!=null){where+=" AND sm.plant_id=?";args.add(f.plantId());}if(f.sourceId()!=null){where+=" AND CONCAT('file:',e.source_asset_id)=?";args.add(f.sourceId());}if(f.plantPart()!=null){where+=" AND sm.plant_part=?";args.add(f.plantPart());}if(f.unlinked()!=null)where+=f.unlinked()?" AND sm.plant_id IS NULL":" AND sm.plant_id IS NOT NULL";if(f.status()!=null&&!f.status().equals("LEGACY_REVIEW_REQUIRED"))where+=" AND 1=0";
   if(f.kind()!=null){where+=" AND EXISTS(SELECT 1 FROM measurement m WHERE m.research_sample_id=sm.id AND m.measurement_kind=?)";args.add(f.kind());}if(f.q()!=null){where+=" AND (sm.sample_label LIKE ? ESCAPE '!' OR sm.identification_text LIKE ? ESCAPE '!' OR sm.source_sample_key LIKE ? ESCAPE '!')";args.add(like(f.q()));args.add(like(f.q()));args.add(like(f.q()));}args.add(size);
   result.addAll(jdbc.queryForList("SELECT CONCAT('course-sample:',sm.id) AS id,CAST(sm.id AS CHAR) AS native_id,COALESCE(sm.source_sample_key,sm.sample_key) AS sample_key,st.study_key,COALESCE(sm.sample_label,sm.identification_text,sm.source_sample_key) AS label,sm.plant_id,COALESCE(sm.taxon_id,p.taxon_id) AS taxon_id,IF(sm.linkage_state='LINKED' AND t.identity_state='VERIFIED','VERIFIED','SOURCE_REPORTED') AS identity_state,sm.plant_part,st.methods_summary AS method,sm.linkage_state,CONCAT('file:',e.source_asset_id) AS source_id,(SELECT COUNT(*) FROM measurement m WHERE m.research_sample_id=sm.id) AS measurement_count FROM research_sample sm JOIN research_study st ON st.id=sm.research_study_id LEFT JOIN plant p ON p.id=sm.plant_id LEFT JOIN taxon t ON t.id=COALESCE(sm.taxon_id,p.taxon_id) LEFT JOIN evidence e ON e.id=sm.evidence_id"+where+" ORDER BY id LIMIT ?",args.toArray()));
  }result.sort(Comparator.comparing(r->r.get("id").toString()));return result.stream().limit(size).toList();
 }
 public List<Map<String,Object>> points(boolean admin,List<String> sampleIds,String kind,String after,int size){return points(admin,sampleIds,kind,after,size,null);}
 private List<Map<String,Object>> points(boolean admin,List<String> sampleIds,String kind,String after,int size,String exact){var args=new ArrayList<Object>();String where=" WHERE CONCAT('candidate:',o.candidate_id)>? ";args.add(after);List<String> scientific=sampleIds.stream().filter(s->s.startsWith("sample:")).map(s->s.substring(7)).toList();String filter=scientific.isEmpty()?" AND 1=0":" AND o.sample_id IN("+marks(scientific.size())+")";where+=filter;args.addAll(scientific);if(kind!=null){where+=" AND o.kind=?";args.add(kind);}if(exact!=null){where+=" AND CONCAT('candidate:',o.candidate_id)=?";args.add(exact);}args.add(size);
  var out=new ArrayList<>(jdbc.queryForList("SELECT CONCAT('candidate:',o.candidate_id) AS id,CONCAT('sample:',o.sample_id) AS sample_id,NULL AS plant_id,NULL AS taxon_id,'UNLINKED' AS identity_state,o.kind,o.analyte,o.raw_value,o.value_numeric,o.unit,o.basis,NULL AS plant_part,NULL AS method,c.normalized_payload"+",c.locator,o.source_id,s.license_state,s.integrity_state,"+state()+" AS review_state,"+(admin?"IF(EXISTS(SELECT 1 FROM published_scientific_fact pf WHERE pf.id=c.id),'PUBLISHED','CANDIDATE')":"IF(f.knowledge_confidence='HUMAN_VERIFIED','PUBLISHED','SOURCE_PUBLIC')")+" AS publication_state,"+(admin?"IF(EXISTS(SELECT 1 FROM published_scientific_fact pf WHERE pf.id=c.id),'HUMAN_VERIFIED','MACHINE_EXTRACTED')":"f.knowledge_confidence")+" AS knowledge_confidence FROM scientific_lipid_observation o JOIN scientific_sample sm ON sm.id=o.sample_id JOIN scientific_candidate c ON c.id=o.candidate_id JOIN scientific_source_version s ON s.id=o.source_id LEFT JOIN scientific_review_state r ON r.candidate_id=c.id"+published(admin)+where+" ORDER BY o.candidate_id LIMIT ?",args.toArray()));
  if(admin){args=new ArrayList<>();where=" WHERE CONCAT('course-measurement:',m.id)>? ";args.add(after);var course=sampleIds.stream().filter(s->s.startsWith("course-sample:")).map(s->Long.parseLong(s.substring(14))).toList();where+=course.isEmpty()?" AND 1=0":" AND sm.id IN("+marks(course.size())+")";args.addAll(course);if(kind!=null){where+=" AND m.measurement_kind=?";args.add(kind);}if(exact!=null){where+=" AND CONCAT('course-measurement:',m.id)=?";args.add(exact);}args.add(size);
   out.addAll(jdbc.queryForList("SELECT CONCAT('course-measurement:',m.id) AS id,CONCAT('course-sample:',sm.id) AS sample_id,sm.plant_id,COALESCE(sm.taxon_id,p.taxon_id) AS taxon_id,IF(sm.linkage_state='LINKED' AND t.identity_state='VERIFIED','VERIFIED','SOURCE_REPORTED') AS identity_state,m.measurement_kind AS kind,m.analyte,m.value_raw AS raw_value,m.value_numeric,m.unit,m.analytical_basis AS basis,sm.plant_part,COALESCE(m.method,st.methods_summary) AS method,'LEGACY_REVIEW_REQUIRED' AS review_state,'CANDIDATE' AS publication_state,CONCAT('file:',e.source_asset_id) AS source_id,'UNKNOWN' AS license_state,'UNKNOWN' AS integrity_state,e.locator FROM measurement m JOIN research_sample sm ON sm.id=m.research_sample_id JOIN research_study st ON st.id=sm.research_study_id LEFT JOIN plant p ON p.id=sm.plant_id LEFT JOIN taxon t ON t.id=COALESCE(sm.taxon_id,p.taxon_id) LEFT JOIN evidence e ON e.id=m.evidence_id"+where+" ORDER BY id LIMIT ?",args.toArray()));
  }out.sort(Comparator.comparing(r->r.get("id").toString()));return out.stream().limit(size).toList();
 }
 public Map<String,Object> point(boolean admin,String id){
  List<String> ids;
  if(id.startsWith("candidate:"))ids=jdbc.queryForList("SELECT CONCAT('sample:',o.sample_id) FROM scientific_lipid_observation o "+published(admin)+" WHERE o.candidate_id=?",String.class,id.substring(10));
  else if(admin)ids=jdbc.queryForList("SELECT CONCAT('course-sample:',research_sample_id) FROM measurement WHERE id=?",String.class,Long.parseLong(id.substring(19)));
  else return null;
  return ids.isEmpty()?null:points(admin,ids,null,"",1,id).stream().filter(r->id.equals(r.get("id"))).findFirst().orElse(null);
 }
 public boolean visibleSample(String id){return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM scientific_lipid_observation o JOIN public_source_record f ON f.id=o.candidate_id WHERE o.sample_id=?)",Boolean.class,id.substring(7));}
 public List<Map<String,Object>> source(String id){if(id==null)return List.of();if(id.startsWith("file:"))return jdbc.queryForList("SELECT CONCAT('file:',id) AS id,SUBSTRING_INDEX(relative_path,'/',-1) AS label,sha256,NULL AS version,'UNKNOWN' AS license_state FROM source_asset WHERE id=?",Long.parseLong(id.substring(5)));return jdbc.queryForList("SELECT id,SUBSTRING_INDEX(dataset,'/',-1) AS label,sha256,version_label AS version,license_state FROM scientific_source_version WHERE id=?",id);}
 public List<Map<String,Object>> plantSearch(String q,int limit){return jdbc.queryForList("SELECT p.id,t.canonical_name AS scientific_name,(SELECT n.name_text FROM plant_name n WHERE n.plant_id=p.id AND n.language_tag LIKE 'zh%' AND n.name_role='COMMON' ORDER BY n.id LIMIT 1) AS name_zh,t.identity_state,'CANDIDATE' AS publication_state FROM plant p LEFT JOIN taxon t ON t.id=p.taxon_id WHERE (? IS NULL OR t.canonical_name LIKE ? ESCAPE '!' OR EXISTS(SELECT 1 FROM plant_name n WHERE n.plant_id=p.id AND n.name_text LIKE ? ESCAPE '!')) ORDER BY p.id LIMIT ?",q,q==null?null:like(q),q==null?null:like(q),limit);}
 public List<Map<String,Object>> plant(long id){return jdbc.queryForList("SELECT p.id,t.canonical_name AS scientific_name,(SELECT n.name_text FROM plant_name n WHERE n.plant_id=p.id AND n.language_tag LIKE 'zh%' AND n.name_role='COMMON' ORDER BY n.id LIMIT 1) AS name_zh,t.identity_state FROM plant p LEFT JOIN taxon t ON t.id=p.taxon_id WHERE p.id=?",id);}
 public List<Map<String,Object>> sourceStats(boolean admin){var out=new ArrayList<>(jdbc.queryForList("SELECT s.id AS stat_key,SUBSTRING_INDEX(s.dataset,'/',-1) AS label,(SELECT COUNT(DISTINCT o.sample_id) FROM scientific_lipid_observation o "+published(admin)+" WHERE o.source_id=s.id) AS records FROM scientific_source_version s ORDER BY s.id LIMIT 100"));if(admin)out.addAll(jdbc.queryForList("SELECT CONCAT('file:',a.id) AS stat_key,SUBSTRING_INDEX(a.relative_path,'/',-1) AS label,COUNT(DISTINCT sm.id) AS records FROM research_sample sm JOIN evidence e ON e.id=sm.evidence_id JOIN source_asset a ON a.id=e.source_asset_id GROUP BY a.id,a.relative_path ORDER BY a.id LIMIT 100"));return out;}
 public long visibleSamples(boolean admin){return admin?number("SELECT (SELECT COUNT(*) FROM scientific_sample)+(SELECT COUNT(*) FROM research_sample)"):number("SELECT COUNT(DISTINCT o.sample_id) FROM scientific_lipid_observation o JOIN public_source_record f ON f.id=o.candidate_id");}
 public long unlinked(boolean admin){return admin?number("SELECT (SELECT COUNT(*) FROM scientific_sample)+(SELECT COUNT(*) FROM research_sample WHERE plant_id IS NULL)"):visibleSamples(false);}
 public List<Map<String,Object>> kinds(boolean admin){var rows=new ArrayList<>(jdbc.queryForList("SELECT o.kind AS stat_key,o.kind AS label,COUNT(*) AS records FROM scientific_lipid_observation o "+published(admin)+" GROUP BY o.kind"));if(admin)rows.addAll(jdbc.queryForList("SELECT measurement_kind AS stat_key,CONCAT('课程 · ',measurement_kind) AS label,COUNT(*) AS records FROM measurement GROUP BY measurement_kind"));var merged=new LinkedHashMap<String,Map<String,Object>>();for(var row:rows){String key=row.get("stat_key").toString();long n=((Number)row.get("records")).longValue();if(merged.containsKey(key))n+=((Number)merged.get(key).get("records")).longValue();merged.put(key,Map.of("stat_key",key,"label",key,"records",n));}return new ArrayList<>(merged.values());}
 public List<Map<String,Object>> states(boolean admin){if(!admin)return jdbc.queryForList("SELECT f.knowledge_confidence AS stat_key,CASE f.knowledge_confidence WHEN 'HUMAN_VERIFIED' THEN '人工核验' WHEN 'SOURCE_REPORTED' THEN '资料中记载' ELSE '自动提取' END AS label,COUNT(*) AS records FROM scientific_lipid_observation o JOIN public_source_record f ON f.id=o.candidate_id GROUP BY f.knowledge_confidence ORDER BY f.knowledge_confidence");var out=new ArrayList<>(jdbc.queryForList("SELECT "+state()+" AS stat_key,CONCAT('独立观测 · ',"+state()+") AS label,COUNT(*) AS records FROM scientific_lipid_observation o JOIN scientific_candidate c ON c.id=o.candidate_id LEFT JOIN scientific_review_state r ON r.candidate_id=c.id GROUP BY stat_key,label"));out.add(Map.of("stat_key","LEGACY_REVIEW_REQUIRED","label","课程登记 · 待具名复核","records",number("SELECT COUNT(*) FROM measurement")));return out;}
 private long number(String sql){return jdbc.queryForObject(sql,Long.class);}
 private static String like(String q){return "%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%";}
 private static String marks(int n){return String.join(",",Collections.nCopies(n,"?"));}
}
